 "content": "def transform(grid):
    # Marker locations (color 6) specify the top-left of repeated copies, offset +1,+2 from marker.
    # The source motif is a 3-row, 5-column colored pattern, as shown by demonstrations.
    h, w = len(grid), len(grid[0])
    out = [[2 for _ in range(w)] for _ in range(h)]
    motif = {(0,0):8,(0,1):5,
             (1,1):5,(1,2):0,(1,3):3,
             (2,1):8,(2,2):9,(2,3):5,(2,4):9}
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                top, left = r-1, c-2
                for (dr,dc), value in motif.items():
                    rr, cc = top+dr, left+dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
